SELECT jsonb_build_object('work_count',count(*),'exact_live_lease',coalesce(bool_and(state='leased' AND fence=1 AND attempt_count=1 AND lease_expires_at>clock_timestamp() AND effect_receipt_id IS NULL AND lease_token_hash=encode(sha256(decode(current_setting('wa.lease_secret'),'hex')),'hex')),false),'attempts',(SELECT count(*) FROM platform.runtime_attempt),'effects',(SELECT count(*) FROM platform.runtime_effect_receipt),'enrollments',(SELECT count(*) FROM app.track_enrollment_receipt)) FROM platform.runtime_work_item WHERE id='927e6a91-e9f9-5a6a-88c0-2c6b7402e5f7';
